from threading import Lock
import rclpy
from rclpy.node import Node

from controller_manager_msgs.srv import ListControllers, SwitchController


class ControllerStateTracker:
    """
    全局控制器状态追踪器。
    用于记录当前需要激活的控制器，支持来自topic和action的请求。
    """
    _instance = None
    _lock = Lock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
                    cls._instance._initialized = False
        return cls._instance

    def __init__(self):
        if self._initialized:
            return
        self._initialized = True
        # 记录需要激活的控制器: {controller_name: True}
        self._required_controllers = {}
        # 记录激活请求的来源: {controller_name: 'topic' or 'action'}
        self._activation_sources = {}
        # 用于action server请求的过期时间(秒)
        self._action_timeout_sec = 5.0

    def set_controller_required(self, controller_name: str, source: str = 'topic'):
        """
        设置某个控制器需要被激活。
        source: 'topic' 或 'action'
        """
        with self._lock:
            self._required_controllers[controller_name] = True
            self._activation_sources[controller_name] = source

    def set_controller_unrequired(self, controller_name: str):
        """设置某个控制器不再需要被激活。"""
        with self._lock:
            if controller_name in self._required_controllers:
                del self._required_controllers[controller_name]
            if controller_name in self._activation_sources:
                del self._activation_sources[controller_name]

    def is_controller_required(self, controller_name: str) -> bool:
        """检查某个控制器是否需要被激活。"""
        with self._lock:
            return self._required_controllers.get(controller_name, False)

    def get_source(self, controller_name: str) -> str:
        """获取控制器激活请求的来源。"""
        with self._lock:
            return self._activation_sources.get(controller_name, None)

    def get_all_required(self) -> list:
        """获取所有需要激活的控制器列表。"""
        with self._lock:
            return list(self._required_controllers.keys())

    def clear_all(self):
        """清空所有控制器请求。"""
        with self._lock:
            self._required_controllers.clear()
            self._activation_sources.clear()


# 全局单例实例
controller_state_tracker = ControllerStateTracker()


class TopicMonitor:
    def __init__(self, name, timeout_sec=0.05):
        self.name = name
        self.timeout_sec = timeout_sec
        self.received = False
        self._prev_received = False
        self.last_received_time = None
        self.last_data = None

    def update_received(self, received):
        self._prev_received = self.received
        self.received = received

    def just_changed(self):
        return self.received != self._prev_received
    
    def activate(self):
        self.received = True

class ControllerInfo:
    def __init__(self, name, type, state, required_command_interfaces, required_state_interfaces):
        self.name = name
        self.type = type
        self.state = state
        self.required_command_interfaces = required_command_interfaces
        self.required_state_interfaces = required_state_interfaces

def check_controller_resource_conflict(ctrl1: ControllerInfo, ctrl2: ControllerInfo) -> bool:
    """
    检查两个控制器的 required_command_interfaces 是否有资源冲突。

    @param ctrl1: 控制器1
    @param ctrl2: 控制器2
    @return: True 表示有冲突（两个控制器需要相同的资源），False 表示无冲突
    """
    set1 = set(ctrl1.required_command_interfaces)
    set2 = set(ctrl2.required_command_interfaces)
    return len(set1 & set2) > 0


def get_active_controllers(controllers: dict) -> dict:
    """
    从控制器列表中筛选出已激活的控制器。

    @param controllers: 控制器列表（list_controllers 的返回值）
    @return: 只包含 state 为 'active' 的控制器列表
    """
    return {name: ctrl for name, ctrl in controllers.items() if ctrl.state == 'active'}


class ServiceNotFoundError(Exception):
    pass


class SingletonServiceCaller:
    """
    控制器管理器服务调用的单例类。

    该类用于为给定的服务名称创建（或复用）服务客户端。
    如果对应的服务客户端已存在，则返回已有客户端；
    否则创建新的客户端并进行复用，避免为同一服务名称重复创建多个客户端资源。

    需要三个参数：Node对象、服务类型、完整限定服务名称，来唯一确定并创建服务客户端。
    """

    _clients = {}

    def __new__(cls, node, service_type, fully_qualified_service_name):
        if (node, fully_qualified_service_name) not in cls._clients:
            cls._clients[(node, fully_qualified_service_name)] = node.create_client(
                service_type, fully_qualified_service_name
            )
            node.get_logger().debug(
                f"Creating a new service client : {fully_qualified_service_name} with node : {node.get_name()}"
            )

        node.get_logger().debug(
            f"Returning the existing service client : {fully_qualified_service_name} for node : {node.get_name()}"
        )
        return cls._clients[(node, fully_qualified_service_name)]

def service_caller(
    node,
    service_name,
    service_type,
    request,
    service_timeout=0.0,
    call_timeout=10.0,
    max_attempts=3,
):
    """
    Abstraction of a service call.

    Has an optional timeout to find the service, receive the answer to a call
    and a mechanism to retry a call of no response is received.

    @param node Node object to be associated with
    @type rclpy.node.Node
    @param service_name Service URL
    @type str
    @param request The request to be sent
    @type service request type
    @param service_timeout Timeout (in seconds) to wait until the service is available. 0 means
    waiting forever, retrying every 10 seconds.
    @type float
    @param call_timeout Timeout (in seconds) for getting a response
    @type float
    @param max_attempts Number of attempts until a valid response is received. With some
    middlewares it can happen, that the service response doesn't reach the client leaving it in
    a waiting state forever.
    @type int
    @return The service response

    """
    namespace = "" if node.get_namespace() == "/" else node.get_namespace()
    fully_qualified_service_name = (
        f"{namespace}/{service_name}" if not service_name.startswith("/") else service_name
    )
    cli = SingletonServiceCaller(node, service_type, fully_qualified_service_name)

    while not cli.service_is_ready():
        node.get_logger().info(
            f"waiting for service {fully_qualified_service_name} to become available..."
        )
        if service_timeout:
            if not cli.wait_for_service(service_timeout):
                raise ServiceNotFoundError(
                    f"Could not contact service {fully_qualified_service_name}"
                )
        elif not cli.wait_for_service(10.0):
            node.get_logger().warn(f"Could not contact service {fully_qualified_service_name}")

    node.get_logger().debug(f"requester: making request: {request}\n")
    future = None
    for attempt in range(max_attempts):
        future = cli.call_async(request)
        try:
            rclpy.spin_until_future_complete(node, future, timeout_sec=call_timeout)
        except RuntimeError as e:
            if 'Executor is already spinning' in str(e):
                # 当executor已经在spin时，使用轮询等待
                import time
                start_time = time.time()
                while not future.done() and (time.time() - start_time) < call_timeout:
                    time.sleep(0.01)
            else:
                raise
        if future.result() is None:
            node.get_logger().warning(
                f"Failed getting a result from calling {fully_qualified_service_name} in "
                f"{call_timeout}. (Attempt {attempt+1} of {max_attempts}.)"
            )
        else:
            return future.result()
    raise RuntimeError(
        f"Could not successfully call service {fully_qualified_service_name} after {max_attempts} attempts."
    )


def list_controllers(node, controller_manager_name, service_timeout=0.0, call_timeout=10.0):
    request = ListControllers.Request()
    result = service_caller(
        node,
        f"{controller_manager_name}/list_controllers",
        ListControllers,
        request,
        service_timeout,
        call_timeout,
    )
    controller_states = {}
    for ctrl in result.controller:
        controller_states[ctrl.name] = ControllerInfo(
            name=ctrl.name,
            type=ctrl.type,
            state=ctrl.state,
            required_command_interfaces=ctrl.required_command_interfaces,
            required_state_interfaces=ctrl.required_state_interfaces,
        )
    return controller_states

def switch_controllers(
    node,
    controller_manager_name,
    deactivate_controllers,
    activate_controllers,
    strict,
    activate_asap,
    timeout,
    call_timeout=10.0,
):
    request = SwitchController.Request()
    request.activate_controllers = activate_controllers
    request.deactivate_controllers = deactivate_controllers
    if strict:
        request.strictness = SwitchController.Request.STRICT
    else:
        request.strictness = SwitchController.Request.BEST_EFFORT
    request.activate_asap = activate_asap
    request.timeout = rclpy.duration.Duration(seconds=timeout).to_msg()
    return service_caller(
        node,
        f"{controller_manager_name}/switch_controller",
        SwitchController,
        request,
        call_timeout=call_timeout,
    )